#!/usr/bin/env python3
"""
Turn three.js's ES-module build into plain <script> files that define a global
THREE, so explainers work when a page is opened straight from disk (file://),
where browsers refuse to load ES modules.

three.js stopped shipping a classic build in r160, so this does the minimum
rewrite by hand: each module body is wrapped in its own function (keeping it
in strict mode, as modules are), its import line becomes a destructuring of
what it imports, and its export list becomes a returned object. The library
code itself is untouched.

Run by hand when upgrading three.js. Get the package and check it first:

    curl -sSfLO https://registry.npmjs.org/three/-/three-<version>.tgz
    # compare: openssl dgst -sha512 -binary three-<version>.tgz | openssl base64 -A
    # against the "integrity" field of https://registry.npmjs.org/three/<version>
    tar -xzf three-<version>.tgz
    python3 js/vendor/three/to_global.py package/

Writes three.global.js, OrbitControls.global.js and BufferGeometryUtils.global.js
next to this script and copies the license. Standard library only.
"""

import json
import re
import shutil
import sys
from pathlib import Path

OUT = Path(__file__).resolve().parent


def specs(text):
    """'A, B as C' -> [('A', 'A'), ('B', 'C')]: (name in source, name outside)."""
    out = []
    for part in text.split(','):
        part = part.strip()
        if not part:
            continue
        m = re.fullmatch(r'(\S+)\s+as\s+(\S+)', part)
        out.append((m.group(1), m.group(2)) if m else (part, part))
    return out


def take(pattern, src, what):
    """Find exactly one statement matching `pattern`, return (match, src without it)."""
    found = list(re.finditer(pattern, src, re.S | re.M))
    if len(found) != 1:
        sys.exit(f'expected one {what}, found {len(found)}; the build layout changed')
    m = found[0]
    return m, src[:m.start()] + src[m.end():]


def obj(pairs):
    """[(local, exported)] -> '{ exported: local, ... }'."""
    return '{ ' + ', '.join(e if e == l else f'{e}: {l}' for l, e in pairs) + ' }'


def destructure(pairs, source):
    """Import specs [(imported, local)] -> 'const { imported: local, ... } = source;'."""
    inner = ', '.join(i if i == l else f'{i}: {l}' for i, l in pairs)
    return f'const {{ {inner} }} = {source};'


def main(pkg):
    pkg = Path(pkg)
    version = json.loads((pkg / 'package.json').read_text())['version']
    core = (pkg / 'build/three.core.js').read_text()
    module = (pkg / 'build/three.module.js').read_text()

    # three.core.js: one export list at the end.
    m, core = take(r'^export \{([^}]*)\};?[ \t]*$', core, 'export list in three.core.js')
    core_exports = specs(m.group(1))

    # three.module.js: imports from core, re-exports some core names, then
    # exports its own (plus imported) names.
    m, module = take(r"^import \{([^}]*)\} from '\./three\.core\.js';[ \t]*$", module, 'import in three.module.js')
    module_imports = specs(m.group(1))
    m, module = take(r"^export \{([^}]*)\} from '\./three\.core\.js';[ \t]*$", module, 're-export in three.module.js')
    reexports = specs(m.group(1))
    m, module = take(r'^export \{([^}]*)\};?[ \t]*$', module, 'export list in three.module.js')
    module_exports = specs(m.group(1))

    for name, text in (('three.core.js', core), ('three.module.js', module)):
        if re.search(r'^\s*(import|export)\b', text, re.M) or 'import.meta' in text:
            sys.exit(f'{name} still has module syntax after rewriting; the build layout changed')

    reexport_obj = ', '.join(f'{e}: core.{l}' for l, e in reexports)
    banner = (
        f'/* three.js r{version.split(".")[1]} ({version}) as a classic script that defines a global THREE.\n'
        f' * Generated by to_global.py from the npm package; the library code is unchanged.\n'
        f' * Copyright 2010-2026 Three.js Authors. MIT license, see LICENSE. */\n'
    )
    out = (
        banner
        + '(function (global) {\n'
        + "'use strict';\n"
        + 'var core = (function () {\n'
        + "'use strict';\n" + core
        + f'\nreturn {obj(core_exports)};\n'
        + '})();\n'
        + 'var renderer = (function (core) {\n'
        + "'use strict';\n"
        + destructure(module_imports, 'core') + '\n'
        + module
        + f'\nreturn Object.assign({{ {reexport_obj} }}, {obj(module_exports)});\n'
        + '})(core);\n'
        + 'global.THREE = Object.assign({}, core, renderer);\n'
        + "})(typeof globalThis !== 'undefined' ? globalThis : this);\n"
    )
    (OUT / 'three.global.js').write_text(out)

    for rel, name, export_as in (
        ('examples/jsm/controls/OrbitControls.js', 'OrbitControls', None),
        ('examples/jsm/utils/BufferGeometryUtils.js', 'BufferGeometryUtils', 'BufferGeometryUtils'),
    ):
        src = (pkg / rel).read_text()
        m, src = take(r"^import \{([^}]*)\} from 'three';[ \t]*$", src, f'import in {rel}')
        imports = specs(m.group(1))
        m, src = take(r'^export \{([^}]*)\};?[ \t]*$', src, f'export list in {rel}')
        exports = specs(m.group(1))
        if export_as:
            attach = f'THREE.{export_as} = {obj(exports)};'
        else:
            attach = '\n'.join(f'THREE.{e} = {l};' for l, e in exports)
        out = (
            f'/* three.js {version} addon {name}, as a classic script that adds to the global THREE.\n'
            f' * Generated by to_global.py from the npm package; load three.global.js first. */\n'
            + '(function (THREE) {\n'
            + "'use strict';\n"
            + destructure(imports, 'THREE') + '\n'
            + src
            + '\n' + attach + '\n'
            + "})((typeof globalThis !== 'undefined' ? globalThis : this).THREE);\n"
        )
        (OUT / f'{name}.global.js').write_text(out)

    shutil.copyfile(pkg / 'LICENSE', OUT / 'LICENSE')
    for f in ('three.global.js', 'OrbitControls.global.js', 'BufferGeometryUtils.global.js'):
        print(f'{f}: {(OUT / f).stat().st_size:,} bytes')


if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    main(sys.argv[1])
